/**
 * For Such a Time
 * ---------------
 * Mordecai's plea comes to Esther: relief will come from another quarter — and who knows but you have come to the kingdom for such a time? Stage: a courtyard with a purple canopy, Mordecai in sackcloth beyond the gate, Esther in the doorway weighing her life; midday stillness.
 *
 * Palette 0x1a0e08 → 0x060402 · light: dusk · hero: gate
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, cityGate, house, column, throne, person, birds } from './esther-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 4045336329, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-21, 0, -58], { name: 'city', r: [0, 0.14, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x140b06 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x110905 });

    /* hero: the gate */
    cityGate(W, group, 0, 0, -6, 1.0, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.16, s: 1.03 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.19, s: 1.11 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.37, s: 1.12 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
